	}
	cancelServerStop()
	if operations != nil {
		shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		if err := operations.Shutdown(shutdownCtx); err != nil {
			logger.Warn("operations shutdown", "error", err)
		}
		cancel()
	}
}

