// TestShutdownAndWatcherBothSeeTheServeError proves the serve error is not
// consumed by whichever caller reads first. The channel previously carried a
// single value, so a goroutine watching Done and a caller inside Shutdown
// raced for it, and the loser observed nil. Both real consumers of this
// package, shoal-tserver and shoal-compactor, watch Done in a goroutine and
// call Shutdown on exit, so a metrics server that failed for a real reason
// could have its error silently dropped.
func TestShutdownAndWatcherBothSeeTheServeError(t *testing.T) {
	server, err := Start("127.0.0.1:0", Handler(NewDependencies(), nil), nil)
	if err != nil {
		t.Fatal(err)
	}
	watched := make(chan error, 1)
	go func() {
		<-server.Done()
		watched <- server.Err()
	}()

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := server.Shutdown(ctx); err != nil {
		t.Fatal(err)
	}
	select {
	case err := <-watched:
		// A clean shutdown reports no serve error to either observer. The
		// point is that both observed the same thing rather than one of them
		// consuming it.
		if err != nil {
			t.Fatalf("watcher saw %v after a clean shutdown", err)
		}
	case <-ctx.Done():
		t.Fatal("watcher never observed the serve loop ending")
	}
	if err := server.Err(); err != nil {
		t.Fatalf("Err after shutdown = %v", err)
	}
}

// TestShutdownIsIdempotent guards the sync.Once path now that Shutdown reads a
// closed channel rather than draining a value.
func TestShutdownIsIdempotent(t *testing.T) {
	server, err := Start("127.0.0.1:0", Handler(NewDependencies(), nil), nil)
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := server.Shutdown(ctx); err != nil {
		t.Fatal(err)
	}
	if err := server.Shutdown(ctx); err != nil {
		t.Fatalf("second shutdown = %v", err)
	}
	select {
	case <-server.Done():
	default:
		t.Fatal("done must remain readable after repeated shutdown")
	}
}

// TestShutdownJoinsEvenWhenTheContextIsAlreadyDone covers the branch the
// happy-path test cannot reach. With an expired context the select's Done case
// is immediately ready and can win before the serve goroutine has closed its
// channel, so returning there would break the join this function promises.
// Close unblocks Serve, so waiting is bounded rather than a deadlock.
//
// It is reachable in practice: shoal-compactor reuses a shutdown context after
// waiting on another server, by which point it may already be expired.
func TestShutdownJoinsEvenWhenTheContextIsAlreadyDone(t *testing.T) {
	server, err := Start("127.0.0.1:0", Handler(NewDependencies(), nil), nil)
	if err != nil {
		t.Fatal(err)
	}
	expired, cancel := context.WithCancel(context.Background())
	cancel()

	done := make(chan error, 1)
	go func() { done <- server.Shutdown(expired) }()

	// Deliberately no assertion on the returned error. Both select cases can
	// be ready at once and Go picks among them at random, and http.Shutdown
	// returns nil when it finishes closing before the context is consulted, so
	// whether a context cause appears is genuinely nondeterministic here. The
	// property under test is the join.
	select {
	case <-done:
	case <-time.After(10 * time.Second):
		t.Fatal("shutdown blocked instead of joining a closed serve loop")
	}

	select {
	case <-server.Done():
	default:
		t.Fatal("shutdown returned on the context before the serve loop ended")
	}
}

// failingListener fails every Accept with a sentinel, so http.Server.Serve
// returns something that is not ErrServerClosed and the serve error path is
// actually reachable.
type failingListener struct {
	addr net.Addr
	err  error
}

// TestConcealWithholdingEnvironmentDefault covers the environment half of the
// wiring. Only the documented value enables the option, so a typo cannot
// silently switch a security control on or off.
func TestConcealWithholdingEnvironmentDefault(t *testing.T) {
	for value, want := range map[string]bool{
		"":      false,
		"1":     true,
		"0":     false,
		"true":  false,
		"yes":   false,
		" 1":    false,
		"1 ":    false,
		"TRUE":  false,
		"enabl": false,
	} {
		t.Run("env="+value, func(t *testing.T) {
			t.Setenv("SHOAL_CONCEAL_WITHHOLDING", value)
			if got := concealWithholdingDefault(); got != want {
				t.Fatalf("SHOAL_CONCEAL_WITHHOLDING=%q resolved to %v, want %v",
					value, got, want)
			}
		})
	}
}

// TestConcealWithholdingFlagIsRegistered proves the flag reaches the real
// parser. A flag that is documented but never defined fails here rather than
// at a deployment that quietly ignores it.
func TestConcealWithholdingFlagIsRegistered(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	// The context is already cancelled, so the command shuts down as soon as
	// it has parsed. An undefined flag fails before that with a parse error.
	err := run(ctx, []string{
		"-data", t.TempDir(), "-listen", "127.0.0.1:0", "-dev-auth",
		"-conceal-withholding",
	}, &lockedBuffer{})
	if err != nil && strings.Contains(err.Error(), "not defined") {
		t.Fatalf("-conceal-withholding is not registered: %v", err)
	}
}

// TestConcealWithholdingReachesTheDeployedService proves the option survives
// composition. Every other test for it calls ConcealWithholding directly, so a
// regression in openService could leave the advertised deployment option
// ineffective while those stay green.
//
// The default case is asserted in the same test rather than separately,
// because the option is only meaningful as a difference: a concealed response
// that happens to match an unconfigured one proves nothing.
func TestConcealWithholdingReachesTheDeployedService(t *testing.T) {
	disclosing, disclosingCtx, closeDisclosing := withholdingDeployment(t, false)
	defer closeDisclosing()
	disclosed, err := disclosing.Documents(
		disclosingCtx, webapi.DocumentsRequest{})
	if err != nil {
		t.Fatalf("documents with disclosure: %v", err)
	}
	if disclosed.Suppressed == 0 {
		t.Fatal("the fixture must actually withhold something, " +
			"or concealment cannot be observed")
	}
	if len(disclosed.Documents) != 0 {
		t.Fatalf("the outsider must read nothing: %#v", disclosed.Documents)
	}

	concealing, concealingCtx, closeConcealing := withholdingDeployment(t, true)
	defer closeConcealing()
	concealed, err := concealing.Documents(
		concealingCtx, webapi.DocumentsRequest{})
	if err != nil {
		t.Fatalf("documents with concealment: %v", err)
	}
	if concealed.Suppressed != 0 || concealed.Restricted != 0 {
		t.Fatalf("-conceal-withholding did not reach the deployed service: %#v",
			concealed)
	}
	if len(concealed.Documents) != 0 {
		t.Fatalf("concealment changed what the outsider reads: %#v",
			concealed.Documents)
	}
}

// withholdingDeployment starts the real composition with the concealment
// option set as a deployment would set it, ingests one document, and returns a
// principal that is authorized to act but holds no grant for that document.
// Its reads are therefore withheld, which is the only state in which the
// counts are observable at all.
func withholdingDeployment(
	t *testing.T, conceal bool,
) (webapi.Service, context.Context, func()) {
	t.Helper()
	root := t.TempDir()
	now := time.Now().UTC().Add(time.Minute)
	authority := auth.NewAuthority()
	opened, err := openService(context.Background(), serviceConfig{
		backend: "embedded", data: filepath.Join(root, "corpus"),
		policyDir: filepath.Join(root, "policy"),
		resolver:  authority.Resolver(), clock: func() time.Time { return now },
		concealWithholding: conceal,
	})
	if err != nil {
		t.Fatal(err)
	}
	if opened.client == nil {
		opened.close()
		t.Skip("embedded service exposes no authorized client")
	}
	ingestCtx, err := authority.Binder().Bind(context.Background(), askDecision(
		t, now, "wiring-ingest",
		auth.OperationIngest, auth.OperationRead, auth.OperationList))
	if err != nil {
		opened.close()
		t.Fatal(err)
	}
	if _, err := opened.client.Ingest(ingestCtx, explorer.Source{
		URI: "shoal://test/withheld.md", Title: "Withheld",
		MediaType: "text/markdown", Content: "# Withheld\n\nrestricted body\n",
	}); err != nil {
		opened.close()
		t.Fatalf("ingest: %v", err)
	}
	// Same domain and operations, but a grant for a source that owns nothing.
	// The ingested document is then withheld from this principal by
	// authorization rather than by absence.
	decision, err := auth.NewDecision(auth.DecisionConfig{
		Subject: "outsider", Actor: "outsider",
		AuthorizationDomain: workspaceAuthorizationDomain,
		AllowedOperations: []auth.Operation{
			auth.OperationList, auth.OperationRead, auth.OperationRetrieve,
		},
		PermittedSourceIDs:    [][]byte{[]byte("shoal-explore-web/other")},
		PermittedPolicyIDs:    [][]byte{[]byte("shoal-explore-web/other-grant")},
		PolicyGeneration:      workspacePolicyGeneration,
		AuthenticationExpires: now.Add(time.Hour),
		RequestID:             "outsider-request",
		CorrelationID:         "outsider-correlation",
	})
	if err != nil {
		opened.close()
		t.Fatal(err)
	}
	ctx, err := authority.Binder().Bind(context.Background(), decision)
	if err != nil {
		opened.close()
		t.Fatal(err)
	}
	return opened.service, ctx, opened.close
}

// concealWithholdingDefault resolves the environment default for
// -conceal-withholding. Only the documented value enables it, so a stray value
// cannot switch concealment on.
//
// The converse does not hold and is worth stating plainly: an unrecognized
// value such as "true" or "1 " leaves concealment off. Exact matching cannot
// prevent accidental disablement, so an operator who depends on concealment
// should set the flag, where a typo is rejected by the parser, rather than the
// environment variable, where it is silently ignored.
func concealWithholdingDefault() bool {
	return os.Getenv("SHOAL_CONCEAL_WITHHOLDING") == "1"
}

func openService(
	ctx context.Context,
	config serviceConfig,
) (openedService, error) {
	closed := openedService{close: func() {}}
	switch config.backend {
	case "embedded":
		runtimeConfig := explorercoord.Config{
			Directory: config.data,
			Domain:    workspacePublicationDomain,
			Owner:     workspaceRuntimeOwner,
			Authority: transaction.Authority{
				Generation:          1,
				Fence:               1,
				Holder:              workspaceRuntimeOwner,
				Mode:                coordination.WriterModeEmbeddedPrimary,
				RetentionGeneration: 1,
				HistoryFloor:        1,
			},
			Clock: config.clock,
		}
		explorerfleetevents.ConfigureHostedRuntime(&runtimeConfig)
		embedded, err := explorercoord.OpenExplorer(
			runtimeConfig, explorer.Options{Embedder: config.embedder})
		if err != nil {
			return closed, err
		}
		corpus := embedded.Explorer
		// The policy catalog is durable and lives in its own directory, not a
		// subdirectory of the corpus: the corpus engine treats every
		// subdirectory as a table, so nesting the store there would corrupt
		// table discovery. A caller that sets only data keeps the legacy
		// sibling layout; -state-dir/-policy-dir place both under one mount.
		policyDir := config.policyDir
		if policyDir == "" {
			policyDir = policyStoreDir(config.data)
		}
		store, err := authorized.OpenDurablePolicyStore(policyDir)
		if err != nil {
			embedded.Close()
			return closed, err
		}
		// A non-empty corpus paired with an empty policy catalog is the
		// signature of a lost or unmounted policy volume: the documents
		// survived but every authorization registration is gone. Refuse rather
		// than serve a silently under-authorized workspace. The development
		// backfill is the sanctioned way to (re)register a pre-durability
		// corpus, so this guard applies only in production (backfill == nil),
		// where the two situations are otherwise indistinguishable.
		if config.backfill == nil {
			if err := refuseSplitBrainStateDirectory(
				ctx, corpus, store, config.data, policyDir); err != nil {
				store.Close()
				embedded.Close()
				return closed, err
			}
		}
		generationReader := config.generationReader
		if isNilFleetDependency(generationReader) {
			generationReader = fixedGenerationReader{
				domain:     workspaceAuthorizationDomain,
				generation: workspacePolicyGeneration,
			}
		}
		client, err := authorizedClient(
			corpus, store, config.resolver, generationReader,
			config.clock, config.mosaic)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		if err := corpus.EnsureInteractionSink(ctx); err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		interactionRecorder, err := interaction.NewRecorder(
			ctx, fleetInteractionSink{durable: corpus, authorized: client})
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		if err := interactionRecorder.SetClock(config.clock); err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		fleetLifecycleRecorder, err := explorerfleet.NewLifecycleRecorderWithReader(
			fleetInteractionSink{durable: corpus, authorized: client}, corpus)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		executors := config.executors
		if executors == nil {
			executors = configuredFleetExecutors{}
		}
		snapshots, err := explorerfleet.NewInteractionSnapshotProvider(corpus)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		fleetRegistry, err := explorerfleet.Compose(
			embedded.Runtime, config.resolver, fleetLifecycleRecorder, snapshots,
			executors, nil, config.clock)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		cursorKey, err := explorerfleetevents.LoadOrCreateCursorKey(ctx, corpus)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		fleetEvents, actionEvents, err :=
			explorerfleetevents.ComposeWithPublisherAndReader(
				embedded.Runtime, workspacePublicationDomain, config.resolver,
				generationReader, func(operation auth.Operation) interaction.ResultSink {
					if sink := client.FleetActionInteractionSink(operation); sink != nil {
						return sink
					}
					return client
				}, corpus, snapshots, fleetRegistry, cursorKey, config.clock,
			)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		actionRecorder, err := explorerfleet.NewActionRecorderWithSnapshots(
			interactionRecorder, snapshots)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		fleetDispatch, err := explorerfleet.ComposeDispatch(
			embedded.Runtime, fleetRegistry, config.resolver, actionRecorder,
			actionEvents, nil, config.clock,
		)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		teamOverview, err := teamoverview.NewService(teamoverview.Config{
			Graph: client, Agents: fleetRegistry, Actions: fleetDispatch,
			Interactions: client, Resolver: config.resolver, Clock: config.clock,
		})
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		boundFleetDispatch, err := newBoundFleetDispatch(
			fleetDispatch, config.resolver)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		boundFleetRegistry, err := newBoundFleetRegistry(
			fleetRegistry, config.resolver)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		// The development-only backfill migrates a corpus whose documents were
		// ingested before the policy catalog was durable: their authorization
		// registrations are absent until re-registered once. A failure here is
		// fatal by design: the workspace must not serve a corpus it could not
		// finish authorizing.
		backfilled, err := config.backfill.run(ctx, client)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		service, err := webapi.NewEmbeddedService(client)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		service.ConcealWithholding(config.concealWithholding)
		if config.ontology != nil {
			// This call is load-bearing; TestOntologyProposalLifecycleUsesStartedEmbeddedWorkspace
			// pins that startup wires -ontology-file into the real EmbeddedService
			// path used by proposal creation, not only into an injected test double.
			if err := service.SetOntologyVersion(*config.ontology); err != nil {
				store.Close()
				embedded.Close()
				return closed, err
			}
		}
		settingsStore, err := workspace.NewDurableStoreWithEngine(
			embedded.Runtime.EmbeddedEngine())
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		choices, err := webapi.NewGovernedOntologyChoices(service)
		if err != nil {
			settingsStore.Close()
			store.Close()
			embedded.Close()
			return closed, err
		}
		settingsProvider, err := workspace.NewProvider(
			settingsStore,
			workspace.ProviderOptions{
				Resolver:         config.resolver,
				GenerationReader: generationReader,
				OntologyChoices:  choices,
				Clock:            config.clock,
			},
		)
		if err != nil {
			settingsStore.Close()
			store.Close()
			embedded.Close()
			return closed, err
		}
		return openedService{
			service:       service,
			settings:      settingsProvider,
			fleetRegistry: boundFleetRegistry,
			fleetDispatch: boundFleetDispatch,
			fleetEvents:   fleetEvents,
			teamOverview:  teamOverview,
			client:        client,
			backfilled:    backfilled,
			close: func() {
				settingsStore.Close()
				store.Close()
				embedded.Close()
			},
		}, nil
	case "remote":
		// The remote backend forwards workspace calls to an upstream Explorer
		// web API over HTTP and has no way to carry the caller's decision
		// across that hop: webapi.RemoteService is a workspace service, not an
		// explorer.Client, so authorized.Client cannot wrap it, and no
		// on-the-wire representation of auth.Decision exists yet. Serving it
		// would mean authenticating at this edge and then calling upstream
		// with no identity at all. Refuse rather than leave that path open.
		return closed, fmt.Errorf(
			"backend remote is unavailable: forwarding the caller's " +
				"authorization decision to an upstream Explorer is not " +
				"implemented, so the upstream call would carry no identity " +
				"(see issue #278, edge identity)")
	default:
		return closed, fmt.Errorf("unknown backend %q", config.backend)
	}
}

