// Run executes every probe. Each runs as a subtest so one failing surface
// reports alone rather than hiding the rest.
func Run(t *testing.T, probes ...Probe) {
	t.Helper()
	if len(probes) == 0 {
		t.Fatal("disclosure conformance requires at least one probe")
	}
	seen := make(map[string]struct{}, len(probes))
	for _, probe := range probes {
		if probe.Name == "" {
			t.Fatal("every disclosure probe requires a name")
		}
		if _, duplicate := seen[probe.Name]; duplicate {
			t.Fatalf("duplicate disclosure probe %q", probe.Name)
		}
		seen[probe.Name] = struct{}{}
		t.Run(probe.Name, func(t *testing.T) {
			runProbe(t, probe)
		})
	}
}

func decodeObject(raw []byte) map[string]json.RawMessage {
	var object map[string]json.RawMessage
	if err := json.Unmarshal(raw, &object); err != nil {
		return nil
	}
	return object
}

// differingFields names the top-level keys that differ, so a failure says what
// leaked rather than only that something did. It is diagnostic output; the
// assertion itself is always the full byte comparison.
func differingFields(withheld, control []byte) []string {
	left, right := decodeObject(withheld), decodeObject(control)
	if left == nil || right == nil {
		return []string{"(responses are not JSON objects)"}
	}
	names := make(map[string]struct{})
	for key := range left {
		names[key] = struct{}{}
	}
	for key := range right {
		names[key] = struct{}{}
	}
	var differing []string
	for key := range names {
		leftValue, leftOK := left[key]
		rightValue, rightOK := right[key]
		switch {
		case leftOK != rightOK:
			differing = append(differing, fmt.Sprintf("%s (present in one)", key))
		case !bytes.Equal(leftValue, rightValue):
			differing = append(differing,
				fmt.Sprintf("%s (%s vs %s)", key, leftValue, rightValue))
		}
	}
	sort.Strings(differing)
	return differing
}

// encode renders a response the way a caller receives it, so the comparison
// covers custom marshaling and omitempty rather than only exported fields.
func encode(value any) ([]byte, error) {
	if value == nil {
		return []byte("null"), nil
	}
	return json.Marshal(value)
}

func runProbe(t *testing.T, probe Probe) {
	t.Helper()
	if probe.Distinguishable && probe.Reason == "" {
		t.Fatal("a deliberately distinguishable surface must record why")
	}
	withheld, err := encode(probe.Withheld)
	if err != nil {
		t.Fatalf("encode withheld response: %v", err)
	}
	control, err := encode(probe.Control)
	if err != nil {
		t.Fatalf("encode control response: %v", err)
	}
	identical := bytes.Equal(withheld, control)
	switch {
	case probe.Distinguishable && identical:
		t.Fatalf(
			"surface no longer discloses withholding, but is declared to on "+
				"purpose (%s)\n  response: %s",
			probe.Reason, withheld)
	case !probe.Distinguishable && !identical:
		t.Fatalf(
			"withheld and control responses differ, so a caller can detect "+
				"that content exists and was withheld\n  fields: %v\n"+
				"  withheld: %s\n  control:  %s",
			differingFields(withheld, control), withheld, control)
	}
}

// Probe is one comparison. Withheld is the response produced when content was
// withheld from the caller; Control is the response for an otherwise identical
// request where nothing was withheld, because nothing matched.
//
// The two must be produced under the same principal and the same request. A
// probe that varies anything else proves nothing.
type Probe struct {
	// Name identifies the surface and request, for example
	// "retrieve/restricted-term".
	Name string
	// Withheld is the response for a request whose matches were withheld.
	Withheld any
	// Control is the response for a request that simply had no matches.
	Control any
	// Distinguishable declares that this surface discloses withholding on
	// purpose. The suite then requires the two responses to differ, so that
	// removing a deliberate disclosure is caught as surely as adding an
	// accidental one.
	Distinguishable bool
	// Reason records why a Distinguishable surface is allowed to disclose.
	// Required when Distinguishable is set, so an accepted trade always
	// carries its justification next to the assertion.
	Reason string
}

// Terms a probe can ask about. They are chosen so each appears in exactly one
// place, which is what makes a comparison meaningful.
const (
	// OpenTerm appears only in the document every principal may read.
	OpenTerm = "seagrass"
	// RestrictedTerm appears only in the document the uncleared principal may
	// not read. Its matches exist and are withheld.
	RestrictedTerm = "thunderbolt"
	// AbsentTerm appears nowhere in the corpus. Its matches do not exist.
	//
	// The whole question this package exists to answer is whether an uncleared
	// principal can tell RestrictedTerm from AbsentTerm.
	AbsentTerm = "zzzzqqqq"
)

// Cleared returns a context for a principal granted both compartments.
func (c *Corpus) Cleared(t *testing.T) context.Context {
	t.Helper()
	return c.bind(t, "cleared",
		[][]byte{c.sourceA, c.sourceB}, [][]byte{c.policyA, c.policyB})
}

// Resolver returns the fixture's trusted decision resolver, for a service that
// binds its own authorization rather than taking a context alone.
func (c *Corpus) Resolver() auth.Resolver { return c.authority.Resolver() }

// Uncleared returns a context for a principal granted only the open
// compartment. Every probe that matters is run as this principal.
func (c *Corpus) Uncleared(t *testing.T) context.Context {
	t.Helper()
	return c.bind(t, "uncleared", [][]byte{c.sourceA}, [][]byte{c.policyA})
}

func (c *Corpus) bind(
	t *testing.T, subject string, sources, policies [][]byte,
) context.Context {
	t.Helper()
	decision, err := auth.NewDecision(auth.DecisionConfig{
		Subject: shoal.ID(subject), Actor: shoal.ID(subject),
		AuthorizationDomain: fixtureDomain,
		AllowedOperations: []auth.Operation{
			auth.OperationIngest, auth.OperationRead, auth.OperationList,
			auth.OperationRetrieve, auth.OperationNeighborhood,
			auth.OperationValidate, auth.OperationConnect,
		},
		PermittedSourceIDs:    sources,
		PermittedPolicyIDs:    policies,
		PolicyGeneration:      1,
		AuthenticationExpires: c.clock().Add(24 * time.Hour),
		RequestID:             shoal.ID(subject + "-request"),
	})
	if err != nil {
		t.Fatal(err)
	}
	ctx, err := c.authority.Binder().Bind(context.Background(), decision)
	if err != nil {
		t.Fatal(err)
	}
	return ctx
}

func (c *Corpus) newClient(
	t *testing.T,
	base explorer.Client,
	store authorized.PolicyStore,
	generations auth.GenerationReader,
	source, policy []byte,
) *authorized.Client {
	t.Helper()
	selector, err := authorized.NewStaticPolicySelector(source, policy)
	if err != nil {
		t.Fatal(err)
	}
	scorer, _ := base.(authorized.VectorScorer)
	interactionWriter, _ := base.(explorer.InteractionWriter)
	interactionReader, _ := base.(explorer.InteractionReader)
	validator, _ := base.(authorized.SnapshotValidator)
	assertions, _ := base.(authorized.DerivedAssertionReader)
	folds, _ := base.(authorized.FoldStore)
	client, err := authorized.NewClient(authorized.Config{
		Base: base, VectorScorer: scorer,
		InteractionWriter: interactionWriter, InteractionReader: interactionReader,
		SnapshotValidator: validator, DerivedAssertionReader: assertions,
		FoldStore: folds, Resolver: c.authority.Resolver(),
		PolicySelector: selector, PolicyStore: store,
		GenerationReader: generations,
		Clock:            c.clock,
	})
	if err != nil {
		t.Fatal(err)
	}
	return client
}

func (r *fixtureGenerations) CurrentPolicyGeneration(
	ctx context.Context, domain []byte,
) (int64, error) {
	if err := ctx.Err(); err != nil {
		return 0, err
	}
	r.mu.RLock()
	defer r.mu.RUnlock()
	return r.generations[string(domain)], nil
}

// NewCorpus builds the fixture: one document in an open compartment and one in
// a restricted compartment, each containing a term that appears nowhere else.
func NewCorpus(t *testing.T) *Corpus {
	t.Helper()
	// The engine stamps snapshots from the wall clock, and a recording whose
	// snapshot postdates it is rejected before any probe runs. A frozen date
	// captured before ingest is therefore always in the past by the time a
	// question is asked. Determinism comes from comparing two calls in one
	// run, not from pinning the clock.
	clock := func() time.Time { return time.Now().UTC() }
	authority, err := auth.NewAuthorityWithClock(clock)
	if err != nil {
		t.Fatal(err)
	}
	base, err := explorer.Open(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = base.Close() })

	corpus := &Corpus{
		authority: authority, clock: clock,
		sourceA: []byte("source-open"), policyA: []byte("policy-open"),
		sourceB: []byte("source-restricted"), policyB: []byte("policy-restricted"),
	}
	generations := &fixtureGenerations{
		generations: map[string]int64{string(fixtureDomain): 1},
	}
	store := authorized.NewMemoryPolicyStore()

	open := corpus.newClient(t, base, store, generations, corpus.sourceA, corpus.policyA)
	restricted := corpus.newClient(t, base, store, generations, corpus.sourceB, corpus.policyB)
	corpus.Client = open

	admin := corpus.Cleared(t)
	if _, err := open.Ingest(admin, explorer.Source{
		URI: "file:///open.txt", Title: "Open", MediaType: explorer.MediaTypeText,
		Content: "the " + OpenTerm + " bed is shallow",
	}); err != nil {
		t.Fatalf("ingest open document: %v", err)
	}
	if _, err := restricted.Ingest(admin, explorer.Source{
		URI: "file:///restricted.txt", Title: "Restricted",
		MediaType: explorer.MediaTypeText,
		Content:   "project " + RestrictedTerm + " ships in spring",
	}); err != nil {
		t.Fatalf("ingest restricted document: %v", err)
	}
	return corpus
}

// Corpus is a two-compartment corpus with two principals of different
// clearance, built from exported APIs only.
type Corpus struct {
	// Client reads the whole corpus. What a caller sees is decided by the
	// decision bound into the context, not by which client is used.
	Client *authorized.Client

	authority *auth.Authority
	clock     func() time.Time
	sourceA   []byte
	policyA   []byte
	sourceB   []byte
	policyB   []byte
}

type fixtureGenerations struct {
	mu          sync.RWMutex
	generations map[string]int64
}

// TestClearedPrincipalSeesRestrictedContent guards the fixture itself. If the
// restricted document were unreadable by everyone, or missing, the uniformity
// tests above would pass trivially.
func TestClearedPrincipalSeesRestrictedContent(t *testing.T) {
	corpus := NewCorpus(t)
	cleared := retrieveTerm(t, corpus, corpus.Cleared(t), RestrictedTerm)
	if len(cleared.Response.Results) == 0 {
		t.Fatal("the cleared principal must see the restricted term")
	}
	if cleared.Disclosure.Suppressed != 0 {
		t.Fatalf("nothing should be withheld from the cleared principal: %#v",
			cleared.Disclosure)
	}
	uncleared := retrieveTerm(t, corpus, corpus.Uncleared(t), RestrictedTerm)
	if len(uncleared.Response.Results) != 0 {
		t.Fatal("the uncleared principal must not see the restricted term")
	}
}

// TestDisclosureCountIsQueryIndependent pins the mechanism the uniformity
// rests on. The count reports how much of the corpus this identity may not
// read, not what matched, so a term that returns a result reports the same
// count as one that returns nothing.
func TestDisclosureCountIsQueryIndependent(t *testing.T) {
	corpus := NewCorpus(t)
	ctx := corpus.Uncleared(t)
	matched := retrieveTerm(t, corpus, ctx, OpenTerm)
	if len(matched.Response.Results) == 0 {
		t.Fatal("the open term must match, or the fixture proves nothing")
	}
	for _, term := range []string{RestrictedTerm, AbsentTerm} {
		other := retrieveTerm(t, corpus, ctx, term)
		if other.Disclosure != matched.Disclosure {
			t.Fatalf("disclosure varies by query: %q reports %#v, %q reports %#v",
				OpenTerm, matched.Disclosure, term, other.Disclosure)
		}
	}
}

// TestRetrievalIsUniformForWithheldAndAbsent is the measurement that should
// have come first. It proves directly, against a real two-compartment corpus,
// that an uncleared principal cannot tell a term whose matches exist and were
// withheld from a term that matches nothing.
//
// The property holds by construction rather than by care: the authorized layer
// removes documents the identity may not read from the search projection
// before scoring, so retrieval never sees them and cannot report on them. The
// disclosure counts are computed over the whole corpus and are therefore
// identical for every query by this identity, including one that returns a
// result. This test exists so that a future change which makes suppression
// query-dependent, and turns a volume signal into a per-term oracle, fails
// here.
func TestRetrievalIsUniformForWithheldAndAbsent(t *testing.T) {
	corpus := NewCorpus(t)
	ctx := corpus.Uncleared(t)
	Run(t, Probe{
		Name:     "retrieve/withheld-vs-absent",
		Withheld: retrieveTerm(t, corpus, ctx, RestrictedTerm),
		Control:  retrieveTerm(t, corpus, ctx, AbsentTerm),
	})
}

func retrieveTerm(
	t *testing.T, corpus *Corpus, ctx context.Context, term string,
) retrievalProbeResult {
	t.Helper()
	response, disclosure, err := corpus.Client.RetrieveWithDisclosure(
		ctx, retrieval.Request{
			Text: term, TopK: 8,
			Modes: []retrieval.Mode{retrieval.ModeLexical}, Explain: true,
		})
	if err != nil {
		t.Fatalf("retrieve %q: %v", term, err)
	}
	return retrievalProbeResult{Response: response, Disclosure: disclosure}
}

import (
	"context"
	"testing"

	"github.com/phrocker/shoal-oss/pkg/explorer/authorized"
	"github.com/phrocker/shoal-oss/pkg/retrieval"
)

type retrievalProbeResult struct {
	Response   retrieval.Response
	Disclosure authorized.Disclosure
}

// TestGroundedAskIsUniformForWithheldAndAbsent answers the question the
// disclosure-count analysis left open. The counts are corpus-wide, so they
// cannot be a per-term oracle. The grounded-ask path runs per request, so if a
// "matches exist but were withheld" outcome were distinguishable from "nothing
// matched" anywhere, this is where it would be.
//
// Nothing here is a test double except the model, which is the deterministic
// offline generator: a real two-compartment corpus, the real authorized
// client, and the real reasoning path.
func TestGroundedAskIsUniformForWithheldAndAbsent(t *testing.T) {
	corpus := disclosureconformance.NewCorpus(t)
	provenance, err := inference.NewModelProvenance("fake", "fake", "", nil, nil)
	if err != nil {
		t.Fatal(err)
	}
	service, err := NewChatService(context.Background(), ChatConfig{
		Client: corpus.Client, Resolver: corpus.Resolver(),
		Generator: model.FakeGenerator{Model: "fake"}, Model: provenance,
		RetrievalModes: []retrieval.Mode{retrieval.ModeLexical},
		Clock:          corpus.Clock(),
	})
	if err != nil {
		t.Fatal(err)
	}
	// Guard the probe. If both sides failed for an unrelated reason the
	// comparison would pass while proving nothing, so first prove the path
	// works: the cleared principal must actually get an answer grounded in the
	// restricted document.
	cleared := askTerm(
		t, service, corpus.Cleared(t), disclosureconformance.RestrictedTerm)
	if cleared.Envelope == nil {
		t.Fatalf("the cleared principal must be answerable, got %q: %s",
			cleared.ErrorCode, cleared.ErrorText)
	}

	ctx := corpus.Uncleared(t)
	withheld := askTerm(t, service, ctx, disclosureconformance.RestrictedTerm)
	absent := askTerm(t, service, ctx, disclosureconformance.AbsentTerm)
	t.Logf("withheld outcome: code=%q text=%q", withheld.ErrorCode, withheld.ErrorText)
	t.Logf("absent   outcome: code=%q text=%q", absent.ErrorCode, absent.ErrorText)
	disclosureconformance.Run(t, disclosureconformance.Probe{
		Name: "ask/withheld-vs-absent", Withheld: withheld, Control: absent,
	})
}

func askTerm(
	t *testing.T, service *ChatService, ctx context.Context, term string,
) askOutcome {
	t.Helper()
	envelope, err := service.Ask(ctx, AskRequest{Question: term, TopK: 8})
	if err != nil {
		return askOutcome{
			ErrorCode: primaryErrorCode(err), ErrorText: err.Error(),
		}
	}
	return askOutcome{Envelope: &envelope}
}

// askOutcome is what a caller can observe from one grounded question: the
// envelope if it succeeded, and the error class and message if it did not.
// Both halves matter. An error that names why a question could not be answered
// is as much a response as a body is.
type askOutcome struct {
	Envelope  *CitationEnvelope `json:"envelope,omitempty"`
	ErrorCode shoal.ErrorCode   `json:"error_code,omitempty"`
	ErrorText string            `json:"error_text,omitempty"`
}

